mapper.select:
SELECT u.id, u.username, u.display_name, u.bio, u.avatar_url, f.id AS follow_id, f.created_at,
       EXISTS (
           SELECT 1 FROM follows f2 WHERE f2.follower_id = #{currentUserId} AND f2.followee_id = u.id
       ) AS followed_by_me
FROM follows f
JOIN users u ON u.id = f.follower_id

    f.followee_id = #{userId}

        AND (f.created_at, f.id) < (#{cursorCreatedAt}, #{cursorId})


ORDER BY f.created_at DESC, f.id DESC
LIMIT #{limit}

